def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c

    # Endgame: exploit known cooperators, defend against defectors
    if n >= 97:
        if opp_d <= 2:
            return 'D'
        if opp_d * 2 < n:
            return 'D' if rng.random() < 0.8 else 'C'
        return 'D'

    # Detect unconditional cooperator: many C from opponent even after we defected
    if n >= 8:
        dc = 0
        cd = 0
        for a, b in history:
            if a == 'D' and b == 'C':
                dc += 1
            elif a == 'C' and b == 'D':
                cd += 1
        # If they keep cooperating despite our defections, exploit moderately
        if dc >= 3 and opp_d <= max(1, n // 10):
            # Cooperate mostly to keep them cooperating, defect occasionally
            if n >= 70:
                return 'D' if rng.random() < 0.55 else 'C'
            return 'D' if rng.random() < 0.12 else 'C'

    # Opponent nearly always defects: defect, with rare probes
    if n >= 5 and opp_d * 4 >= n * 3:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Recent window analysis
    w = 8 if n >= 8 else n
    recent = history[-w:]
    r_opp_d = sum(1 for x in recent if x[1] == 'D')
    r_opp_c = w - r_opp_d
    r_me_d = sum(1 for x in recent if x[0] == 'D')

    # Sustained opponent defection recently
    if r_opp_d >= 3:
        if r_opp_d >= w - 1:
            return 'D'
        # Mixed: reciprocal with forgiveness
        if recent[-1][1] == 'C':
            # Opponent just cooperated, reward with C
            return 'C'
        # Opponent defected; retaliate but sometimes forgive if they're recovering
        if r_opp_c >= 3 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent mostly cooperating: keep cooperating, occasional probe
    if recent[-1][1] == 'C':
        if n > 5 and r_me_d == 0 and rng.random() < 0.04 and n < 90:
            return 'D'
        # Exploit more aggressively late
        if n >= 80 and opp_d <= 3 and rng.random() < 0.4:
            return 'D'
        return 'C'

    # Recent[-1] is D, but r_opp_d < 3 (isolated defection)
    # Forgive lightly, retaliate mostly
    if r_opp_d == 1 and n >= 6:
        # Was it a one-off? Check if there's any D earlier in the match
        if opp_d == 1:
            # First defection, all else C -> likely TFT punishing our probe
            if r_me_d >= 1:
                # We probed, they retaliated; restore cooperation
                return 'C'
            return 'C'
        # Forgive with modest probability
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    if recent[-1][1] == 'D':
        return 'D'

    return 'C'
